#!/usr/bin/env bun
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import {
  GEMINI_ROOT,
  MEMORY_DIR,
  RULES_DIR,
  writeIfChanged,
} from "./lib.ts";
import { indexAll } from "./learn.ts";

export function buildGeminiInstructions(): string {
  const parts: string[] = [
    "<!-- Generated by ~/.gemini/scripts/sync.ts from rules/ and memory/; edit those sources instead. -->",
    "",
  ];
  if (existsSync(RULES_DIR)) {
    for (const name of readdirSync(RULES_DIR).sort()) {
      if (!name.endsWith(".md")) continue;
      const body = readFileSync(join(RULES_DIR, name), "utf8").trim();
      if (body) parts.push(body, "");
    }
  }
  const memIdx = join(MEMORY_DIR, "MEMORY.md");
  if (existsSync(memIdx)) {
    const body = readFileSync(memIdx, "utf8")
      .trim()
      .replace(
        /\]\((?!https?:|file:|\/|~)([^)#\s]+\.md)\)/g,
        `](~/.gemini/memory/$1)`,
      );
    if (body) parts.push("## Memory", "", body, "");
  }
  return parts.join("\n").replace(/\n{3,}/g, "\n\n");
}

export function syncAll(): { changed: boolean; indexedFiles: number; indexedChanged: number } {
  const content = buildGeminiInstructions();
  const changed = writeIfChanged(join(GEMINI_ROOT, "GEMINI.md"), content);
  const stats = indexAll();
  return {
    changed,
    indexedFiles: stats.files,
    indexedChanged: stats.changed,
  };
}

if (import.meta.main) {
  const res = syncAll();
  console.log(
    `Synced GEMINI.md (${res.changed ? "updated" : "unchanged"}) and indexed ${res.indexedFiles} file(s) (${res.indexedChanged} changed).`,
  );
}
